const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;
const now = Date.now();

const leads = $input.all().map(item => item.json);

// Dedup guard: leads with sequence_track === 'smartplan' are owned by a KW
// Command SmartPlan (enrolled manually in agent.kw.com). This workflow must
// skip them so a lead never gets AICC-native AND SmartPlan outreach at once.
// See REAL_ESTATE_ASSETS.md (Sharon Traylor dual-track incident) for why this
// guard exists. Leads default to sequence_track = 'aicc' so nothing here
// changes for leads Kareesa hasn't explicitly moved to a SmartPlan.
const stale = leads.filter(lead => {
  if (lead.sequence_track === 'smartplan' || lead.sequence_track === 'none') return false;
  if (['closed', 'lost'].includes(lead.status)) return false;
  if (!lead.last_contact_at) return true;
  return (now - new Date(lead.last_contact_at).getTime()) >= THREE_DAYS_MS;
});

if (stale.length === 0) {
  return [{ json: { skip: true, message: 'All leads contacted within 3 days (or on a different sequence track)' } }];
}

return stale.map(lead => ({ json: lead }));
